import base64
import json
import logging
import time
import websocket

from .keys.mapper import SamsungTVKeys


class SamsungTV():

    _URL_FORMAT = 'ws://{host}:{port}/api/v2/channels/samsung.remote.control?name={name}'

    _KEY_INTERVAL = 1.5

    def __init__(self, host, port=8001, name='SamsungTvRemote'):
        self.connection = websocket.create_connection(
            self._URL_FORMAT.format(**{
                'host': host, 
                'port': port, 
                'name': self._serialize_string(name)
            })
        )

        response = json.loads(self.connection.recv())
        if response['event'] != 'ms.channel.connect':
            self.close()
            raise Exception(response)

    def __exit__(self, type, value, traceback):
        self.close()

    def _serialize_string(self, string):
        if isinstance(string, str):
            string = str.encode(string)
        return base64.b64encode(string).decode('utf-8')

    def close(self):
        if self.connection:
            self.connection.close()
            self.connection = None
            logging.debug('Connection closed.')

    def send_key(self, key, repeat=1):
        for n in range(repeat):
            payload = json.dumps({
                'method': 'ms.remote.control',
                'params': {
                    'Cmd': 'Click',
                    'DataOfCmd': key,
                    'Option': 'false',
                    'TypeOfRemote': 'SendRemoteKey'
                }
            })

            logging.info('Sending key %s', key)
            self.connection.send(payload)
            time.sleep(self._KEY_INTERVAL)

    # power
    def power(self):
        self.send_key(SamsungTVKeys.POWER)

    # menu
    def home(self):
        self.send_key(SamsungTVKeys.HOME)

    def menu(self):
        self.send_key(SamsungTVKeys.MENU)

    def source(self):
        self.send_key(SamsungTVKeys.SOURCE)

    def guide(self):
        self.send_key(SamsungTVKeys.GUIDE)

    def tools(self):
        self.send_key(SamsungTVKeys.TOOLS)

    def info(self):
        self.send_key(SamsungTVKeys.INFO)

    # navigation
    def up(self, count=1):
        self.send_key(SamsungTVKeys.UP, count)

    def down(self, count=1):
        self.send_key(SamsungTVKeys.DOWN, count)

    def left(self, count=1):
        self.send_key(SamsungTVKeys.LEFT, count)

    def right(self, count=1):
        self.send_key(SamsungTVKeys.RIGHT, count)

    def enter(self, count=1):
        self.send_key(SamsungTVKeys.ENTER, count)

    def back(self, count=1):
        self.send_key(SamsungTVKeys.BACK, count)

    # channel
    def channel_list(self):
        self.send_key(SamsungTVKeys.CHANNEL_LIST)

    def channel(self, ch):
        for c in str(ch):
            self.digit(c)
        self.enter()

    def digit(self, d):
        self.send_key(SamsungTVKeys.digit(d))

    def channel_up(self, count=1):
        self.send_key(SamsungTVKeys.CHANNEL_UP, count)

    def channel_down(self, count=1):
        self.send_key(SamsungTVKeys.CHANNEL_DOWN, count)

    # volume
    def volume_up(self, count=1):
        self.send_key(SamsungTVKeys.VOLUME_UP, count)

    def volume_down(self, count=1):
        self.send_key(SamsungTVKeys.VOLUME_DOWN, count)

    def mute(self):
        self.send_key(SamsungTVKeys.MUTE)

    # extra
    def red(self):
        self.send_key(SamsungTVKeys.RED)

    def green(self):
        self.send_key(SamsungTVKeys.GREEN)

    def yellow(self):
        self.send_key(SamsungTVKeys.YELLOW)

    def blue(self):
        self.send_key(SamsungTVKeys.BLUE)
